            elif i == 3:
                visual = VGroup(*[Arc(radius=.45+.18*k, start_angle=-35*DEGREES, angle=(80+8*k)*DEGREES, color=accent, stroke_width=3).move_to(RIGHT*1.4) for k in range(7)], Line(RIGHT*1.4, RIGHT*2.8+UP*.8, color=accent, stroke_width=3), Line(RIGHT*1.4, RIGHT*2.8+DOWN*.8, color=accent, stroke_width=3))
            else:
                visual = VGroup(*[RegularPolygon(n=6,radius=.24,color=accent,fill_color=accent,fill_opacity=.16).move_to([.4+random.random()*2.2,-1.7+random.random()*3.4,0]) for _ in range(14)])
            sweep=Line(LEFT*7,RIGHT*7,color=accent,stroke_width=5).move_to(UP*3.1).set_opacity(.82)
            self.play(FadeIn(left,shift=RIGHT), FadeIn(checklist,shift=LEFT), FadeIn(visual,scale=.4), sweep.animate.move_to(DOWN*3.1), run_time=1.0)
